const {chromium}=require('C:/Users/Administrator/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');const assert=require('node:assert/strict');
(async()=>{const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});const page=await browser.newPage({viewport:{width:1440,height:1050}}),errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('response',r=>{if(r.status()>=400)errors.push(r.url()+' '+r.status());});
await page.goto('http://localhost:4173/fighting.html');assert.equal(await page.locator('.roster button').count(),12);await page.screenshot({path:__dirname+'/fighting-setup.png',fullPage:true});await page.selectOption('#mode','local');await page.click('#start');await page.waitForFunction(()=>PixelFighting.snapshot.phase==='fight');
