await page.keyboard.down('KeyD');await page.keyboard.down('ArrowLeft');await page.waitForTimeout(700);await page.keyboard.up('KeyD');await page.keyboard.up('ArrowLeft');await page.keyboard.down('ArrowDown');await page.waitForTimeout(80);assert.equal((await page.evaluate(()=>PixelFighting.snapshot)).players[1].guard,true);await page.keyboard.press('KeyJ');await page.waitForTimeout(260);await page.keyboard.up('ArrowDown');s=await page.evaluate(()=>PixelFighting.snapshot);assert(s.players[1].hp<100);await page.waitForTimeout(200);await page.keyboard.press('Digit1');await page.waitForTimeout(250);assert((await page.evaluate(()=>PixelFighting.snapshot)).players[0].hp<100);await page.waitForTimeout(400);await page.keyboard.press('KeyU');await page.waitForTimeout(250);await page.screenshot({path:__dirname+'/fighting-match.png',fullPage:true});await page.keyboard.press('KeyP');const paused=await page.evaluate(()=>PixelFighting.snapshot);await page.waitForTimeout(200);assert.equal((await page.evaluate(()=>PixelFighting.snapshot)).time,paused.time);assert.equal(await page.locator('#modal').isVisible(),true);await page.click('#resume');await page.keyboard.press('Escape');await page.click('#new-match');assert.equal(await page.locator('#setup').isVisible(),true);
for(const id of ['explorer','soldier','mystic','dora','goku','nezha']){await page.locator('#p1-roster [data-character="'+id+'"]').click();await page.selectOption('#mode','ai');await page.click('#start');await page.waitForFunction(()=>PixelFighting.snapshot.phase==='fight');assert.equal((await page.evaluate(()=>PixelFighting.snapshot)).players[0].id,id);await page.keyboard.press('KeyU');await page.waitForTimeout(300);await page.keyboard.press('KeyP');await page.click('#new-match');}
await page.setViewportSize({width:390,height:844});await page.screenshot({path:__dirname+'/fighting-mobile.png',fullPage:true});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));assert.deepEqual(errors,[]);console.log('PASS local 2P movement/jumps/guard/attacks, pause, setup, six AI fighters, mobile layout; no browser errors');await browser.close();})().catch(e=>{console.error(e);process.exit(1);});
